import csv
import io


def parse_csv(raw_csv: str):
    expected_columns = [
        "indicator",
        "type",
        "threat",
        "confidence",
        "recommended_action",
        "source_url",
        "description",
        "notes",
        "sources",
    ]

    try:
        records = list(
            csv.reader(
                io.StringIO(raw_csv, newline=""),
                delimiter=",",
                quotechar='"',
                strict=False,
            )
        )
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            try:
                records.extend(
                    csv.reader(
                        [line],
                        delimiter=",",
                        quotechar='"',
                        strict=False,
                    )
                )
            except csv.Error:
                records.append([line])

    def normalize(value):
        return value.lstrip("\ufeff").strip().lower()

    header_index = None
    columns = expected_columns
    expected_normalized = [normalize(column) for column in expected_columns]

    for index, record in enumerate(records):
        normalized = [normalize(value) for value in record]
        matches = sum(
            1
            for position, name in enumerate(expected_normalized)
            if position < len(normalized) and normalized[position] == name
        )
        if (
            len(normalized) >= len(expected_normalized)
            and normalized[:len(expected_normalized)] == expected_normalized
        ) or matches >= 7:
            header_index = index
            columns = [
                value.lstrip("\ufeff").strip()
                for value in record[:len(expected_columns)]
            ]
            break

    data_records = records[header_index + 1:] if header_index is not None else records
    width = len(columns)
    rows = []

    for record in data_records:
        if not record or all(not value.strip() for value in record):
            continue

        row = list(record)
        if len(row) > width and width >= 9:
            overflow = len(row) - width
            description_end = 6 + overflow
            row = (
                row[:6]
                + [",".join(row[6:description_end])]
                + row[description_end:]
            )
        if len(row) > width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        elif len(row) < width:
            row.extend([""] * (width - len(row)))

        rows.append([value for value in row])

    return {"columns": columns, "rows": rows}
